// ═══ EnumSet: bit-vector magic ═══
enum TradeStatus { PENDING, VALIDATED, SETTLED, FAILED, CANCELLED }

EnumSet<TradeStatus> active = EnumSet.of(TradeStatus.PENDING, TradeStatus.VALIDATED);
// Internal: long = 0b00011 (bit 0 = PENDING, bit 1 = VALIDATED)

active.add(TradeStatus.SETTLED);     // flip bit 2 → 0b00111
active.contains(TradeStatus.FAILED); // check bit 3 → false
active.remove(TradeStatus.PENDING);  // clear bit 0 → 0b00110

// Factory methods:
EnumSet.allOf(TradeStatus.class);    // all constants
EnumSet.noneOf(TradeStatus.class);   // empty
EnumSet.range(TradeStatus.PENDING, TradeStatus.SETTLED);  // PENDING, VALIDATED, SETTLED
EnumSet.complementOf(active);        // everything NOT in active

// ═══ EnumMap: array indexed by ordinal ═══
EnumMap<TradeStatus, Integer> counts = new EnumMap<>(TradeStatus.class);
counts.put(TradeStatus.PENDING, 150);
counts.put(TradeStatus.SETTLED, 800);
// Internal: Object[5] → index 0 = PENDING → 150, index 2 = SETTLED → 800
// No hashing! Direct array access by ordinal()!

counts.get(TradeStatus.PENDING);  // array[0] → 150. O(1), zero hash computation!

// ═══ PERFORMANCE COMPARISON ═══
// EnumSet.contains():  1 bitwise AND operation  → ~2ns
// HashSet.contains():  hashCode() + bucket + equals()  → ~20ns (10x slower!)
// EnumSet memory (5 enums): 1 long = 8 bytes
// HashSet memory (5 enums): 5 Nodes × ~48 bytes = ~240 bytes (30x more!)

// EnumMap.get():  1 array access → ~2ns
// HashMap.get():  hashCode() + bucket + equals() → ~20ns
// EnumMap memory: 1 array of 5 slots → ~40 bytes
// HashMap memory: Node[] + 5 Nodes → ~400 bytes (10x more!)
